): (Coin<CoinType>, u64) {
    assert!(ctoken_amount != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();

    let asset = self.assets.load_by_type(name);
    assert!(!asset.withdraw_paused(), error::withdraw_paused_for_asset());


    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // refresh all interest
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
    refresh_obligation_assets_interest<MarketType>(&self.assets, emode_group, &mut self.reserves, obligation, now);

    let ctoken = obligation.withdraw_ctokens(ctoken_amount);
    let ctokens_left = obligation.ctoken_amount_by_coin(name);

    // TODO: if the asset is not collateral, skip obligation safety check
    let is_obligation_safe = is_obligation_safe(
        self.emode_group_registry.borrow_emode_group(obligation.emode_group()),
        &self.reserves,
        &self.ema_spot_tolerance,

        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );
    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());

    let reserve = self.reserves.load_mut_by_type(name);
    let deposit = reserve.burn_ctokens<MarketType, CoinType>(ctoken.into_coin(ctx));

    // rate limit deposit withdraw
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
    emode.borrow_mut_deposit_limiter().add_outflow(
        now,
        deposit.value(),
    );

    // update adl

    // use ceiling, slighly more 
    let total_deposit = reserve.total_deposit_plus_interest().ceil();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
    adl.try_stop_collateral_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), total_deposit);



    (deposit.into_coin(ctx), ctokens_left)
}

public(package) fun handle_borrow<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    borrow_amount: u64,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
): (Balance<CoinType>, Decimal, Decimal) {
    assert!(borrow_amount != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();



    // basic checks
    let asset = self.assets.load_mut_by_type(name);
    assert!(!asset.borrow_paused(), error::borrow_paused_for_asset());



    // load data for later checks
    let asset_config = asset.asset_config();
    let min_borrow_amount = asset_config.min_borrow_amount();
    let asset_max_borrow_amount = asset_config.max_borrow_amount();


    let obligation = self
        .obligations
        .borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
    let asset_name = type_name::with_defining_ids<CoinType>();

    // make sure the outflow is rate limited
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), asset_name);
    let emode_max_borrow_amount = emode.borrow().max_borrow_amount();
    emode.borrow_mut_borrow_limiter().add_outflow(now, borrow_amount);

    let obligation_old_total_borrow_amount = if (!obligation.has_debt(name)) { float::zero() } else { obligation.debt(name).unsafe_debt_amount() };

    // refresh only borrow, practically, obligation owner can borrow a bit more due to collateral interest
    refresh_obligation_borrow_interest_with_new_borrow<MarketType>(name, &self.assets, &mut self.reserves, obligation, now);

    // update obligation
    let borrow_index = self.reserves.load_by_type(name).borrow_index().value();

    obligation.try_borrow_asset<MarketType, CoinType>(borrow_amount, borrow_index);
    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);

    // interest updated, should be up to date
    let obligation_new_total_borrow_amount = obligation.debt(name).unsafe_debt_amount();
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());


    // make sure the emode group borrow limit is not breached
    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_total_borrow_amount, obligation_new_total_borrow_amount);
    assert!(emode_group_total_borrow.le(math::float::from(emode_max_borrow_amount)), error::emode_borrow_limit_exceeded());

    let is_obligation_safe = is_obligation_safe(
        emode_group,
        &self.reserves,
        &self.ema_spot_tolerance,

        self.obligations.borrow(obligation_id),
        coin_decimals_registry,
        x_oracle,
        clock,
    );
    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());

    // perform borrow
    let reserve = self.reserves.load_mut_by_type(name);
    let balance = reserve.borrow_amount<MarketType, CoinType>(borrow_amount);

/// @title Module for handling the liquidation request
/// @notice adopts soft liquidation. Liquidation amount should be no bigger than the amount that would drecrease the risk level of obligation to 1.
module protocol::liquidate;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::Coin;
use sui::event::emit;
use x_oracle::user_oracle::get_price;
use x_oracle::x_oracle::XOracle;
use math::float::Decimal;
use protocol::liquidity_miner::{get_borrow_reward_type, get_deposit_reward_type};
use protocol::app::{ProtocolApp, PackageCallerCap};

public enum LiquidationType has copy, drop{
    NormalLiquidation,
    ADLBorrow,
    ADLCollateral,
}

public struct LiquidateEvent has copy, drop {
    liquidator: address,
    liquidation_type: LiquidationType,

    market: TypeName,
    obligation: ID,


    collateral_price: Decimal,
    debt_price: Decimal,

    collateral_type: TypeName,
    seized_ctoken_amount: u64,
    seized_collateral_amount: u64,
    ctokens_remaining: u64,

    debt_type: TypeName,
    total_borrow_remaining: Decimal,
    borrow_index: Decimal,
    repay_amount: u64,
    refund_amount: u64,

    timestamp: u64,
}

fun pre_liquidation_check<MarketType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,
    market: &Market<MarketType>,
    permission: u8,
) {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    app.ensure_has_permission(object::id(cap), permission);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());
}

fun post_liquidation<MarketType, DebtType, CollateralType>(
    now: u64,
    repay_amount: u64,
    refund_amount: u64,
    liquidation_type: LiquidationType,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    collateral_amount: u64,
    ctoken_amount: u64,

    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &TxContext,
) {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let obligation = market.borrow_obligation(obligation_id);
    let oracle = market.emode_registry().borrow_emode_group(obligation.emode_group()).get_oracle_base_token();

    let total_ctoken_amount = obligation.ctoken_amount_by_coin(collateral_type);
    let (total_borrow, borrow_index) = if (obligation.has_debt(debt_type)) {
        let debt = obligation.debt(debt_type);
        (debt.unsafe_debt_amount(), *debt.borrow_index())
    }  else {
        (math::float::zero(), math::float::one())
    };

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, DebtType>(
        get_borrow_reward_type(),
        obligation_id,
        total_borrow.floor(),
        clock
    );
    miner.update_obligation_reward_manager<MarketType, CollateralType>(
        get_deposit_reward_type(),
        obligation_id,
        total_ctoken_amount,
        clock
    );

    emit(LiquidateEvent {
        liquidator: ctx.sender(),
        liquidation_type,

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_id,

        debt_type,
        collateral_type,

        collateral_price: get_price(x_oracle, type_name::with_defining_ids<CollateralType>(), oracle, clock),
        debt_price: get_price(x_oracle, type_name::with_defining_ids<DebtType>(), oracle, clock),

        seized_ctoken_amount: ctoken_amount,
        seized_collateral_amount: collateral_amount,
        ctokens_remaining: total_ctoken_amount,

        total_borrow_remaining: total_borrow,
        borrow_index,
        repay_amount,
        refund_amount,

        timestamp: now,
    });
}

#[allow(lint(self_transfer))]
public fun liquidate<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let (collateral_balance, refund) = liquidate_as_coin<MarketType, DebtType, CollateralType>(
        app,
        cap,
        obligation_id, 
        market, 
        available_repay_coin, 
        coin_decimals_registry, 
        x_oracle, 
        clock, 
        ctx
    );
    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

public fun liquidate_as_coin<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::liquidation());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_liquidation<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount,
        refund.value(),
        LiquidationType::NormalLiquidation, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    (collateral_balance, refund)
}

#[allow(lint(self_transfer))]
public fun liquidate_adl_borrow<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::adl());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_debt_auto_deleverage<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount,
        refund.value(),
        LiquidationType::ADLBorrow, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

#[allow(lint(self_transfer))]
public fun liquidate_adl_deposit<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::adl());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount, 
        refund.value(),
        LiquidationType::ADLCollateral, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

